<?php require __DIR__.'/bootstrap.php';require_admin();$zones=read_json('delivery-zones.json',[]);$settings=read_json('settings.json',[]);$message='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();if(($_POST['action']??'')==='settings'){$settings['min_lead_hours']=max(0,min(720,(int)($_POST['min_lead_hours']??48)));$settings['opening_hours']=trim((string)($_POST['opening_hours']??''));$settings['free_delivery_threshold']=max(0,(float)($_POST['free_delivery_threshold']??0));write_json('settings.json',$settings);$message='Settings saved. Lead-time and opening-hours values in config.php should also be kept consistent.';}elseif(($_POST['action']??'')==='zones'){$names=$_POST['zone_name']??[];$fees=$_POST['zone_fee']??[];$enabled=$_POST['zone_enabled']??[];$new=[];foreach($names as $i=>$name){$name=trim((string)$name);if($name==='')continue;$new[]=['id'=>(string)($_POST['zone_id'][$i]??'zone-'.bin2hex(random_bytes(4))),'name'=>$name,'fee'=>max(0,(float)($fees[$i]??0)),'enabled'=>isset($enabled[$i])];}for($i=0;$i<count($_POST['new_zone_name']??[]);$i++){ $name=trim((string)$_POST['new_zone_name'][$i]);if($name!=='')$new[]=['id'=>'zone-'.bin2hex(random_bytes(4)),'name'=>$name,'fee'=>max(0,(float)($_POST['new_zone_fee'][$i]??0)),'enabled'=>true];}write_json('delivery-zones.json',$new);$zones=$new;$message='Delivery zones saved.';}}site_header('Delivery settings'); ?>
<div class="admin-shell"><div class="eyebrow">Owner workspace</div><h1 style="font:42px 'Playfair Display',serif">Delivery & settings</h1><nav class="admin-nav"><a href="admin.php">Overview</a><a href="admin-products.php">Products</a><a href="admin-orders.php">Orders</a><a href="admin-settings.php">Settings</a><a href="admin-gallery.php">Gallery</a><a href="admin-notifications.php">Notifications</a><a href="admin-subscribers.php">Newsletter</a><a href="admin-requests.php">Custom requests</a><a href="admin-logout.php">Sign out</a></nav><?php if($message)echo '<div class="alert success">'.e($message).'</div>'; ?><div class="cart-layout"><form class="card-panel" method="post"><h2>Preparation settings</h2><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="settings"><div class="field"><label>Minimum preparation lead time (hours)</label><input type="number" min="0" max="720" name="min_lead_hours" value="<?= (int)($settings['min_lead_hours']??48) ?>"></div><div class="field"><label>Opening hours</label><input name="opening_hours" value="<?= e($settings['opening_hours']??'Monday–Saturday, 9 AM–6 PM') ?>"></div><div class="field"><label>Free delivery threshold (0 = disabled)</label><input type="number" min="0" name="free_delivery_threshold" value="<?= (float)($settings['free_delivery_threshold']??0) ?>"></div><button class="button" type="submit">Save settings</button></form><form class="card-panel" method="post"><h2>Delivery zones</h2><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="zones"><?php foreach($zones as $i=>$z): ?><div class="field"><label>Zone name</label><input name="zone_name[]" value="<?= e($z['name']) ?>"><input type="hidden" name="zone_id[]" value="<?= e($z['id']) ?>"></div><div class="field"><label>Fee (NGN)</label><input type="number" name="zone_fee[]" min="0" value="<?= (float)$z['fee'] ?>"></div><label><input type="checkbox" name="zone_enabled[<?= $i ?>]" value="1" <?= !empty($z['enabled'])?'checked':'' ?>> Enabled</label><hr><?php endforeach; ?><h3>Add a zone</h3><div class="field"><label>Zone name</label><input name="new_zone_name[]" placeholder="e.g. Gwarinpa"></div><div class="field"><label>Fee</label><input type="number" name="new_zone_fee[]" min="0" value="0"></div><button class="button" type="submit">Save delivery zones</button></form></div></div><?php site_footer(); ?>
